   300→## src/hooks/useDashboardData.ts
   301→```
   302→import { useState, useEffect, useMemo, useCallback } from 'react';
   303→import type { GewohnheitenVerwaltung, TaeglicherCheckIn, TaeglicheEintraege } from '@/types/app';
   304→import { LivingAppsService } from '@/services/livingAppsService';
   305→
   306→export function useDashboardData() {
   307→  const [gewohnheitenVerwaltung, setGewohnheitenVerwaltung] = useState<GewohnheitenVerwaltung[]>([]);
   308→  const [taeglicherCheckIn, setTaeglicherCheckIn] = useState<TaeglicherCheckIn[]>([]);
   309→  const [taeglicheEintraege, setTaeglicheEintraege] = useState<TaeglicheEintraege[]>([]);
   310→  const [loading, setLoading] = useState(true);
   311→  const [error, setError] = useState<Error | null>(null);
   312→
   313→  const fetchAll = useCallback(async () => {
   314→    setError(null);
   315→    try {
   316→      const [gewohnheitenVerwaltungData, taeglicherCheckInData, taeglicheEintraegeData] = await Promise.all([
   317→        LivingAppsService.getGewohnheitenVerwaltung(),
   318→        LivingAppsService.getTaeglicherCheckIn(),
   319→        LivingAppsService.getTaeglicheEintraege(),
   320→      ]);
   321→      setGewohnheitenVerwaltung(gewohnheitenVerwaltungData);
   322→      setTaeglicherCheckIn(taeglicherCheckInData);
   323→      setTaeglicheEintraege(taeglicheEintraegeData);
   324→    } catch (err) {
   325→      setError(err instanceof Error ? err : new Error('Fehler beim Laden der Daten'));
   326→    } finally {
   327→      setLoading(false);
   328→    }
   329→  }, []);
   330→
   331→  useEffect(() => { fetchAll(); }, [fetchAll]);
   332→
   333→  const gewohnheitenVerwaltungMap = useMemo(() => {
   334→    const m = new Map<string, GewohnheitenVerwaltung>();
   335→    gewohnheitenVerwaltung.forEach(r => m.set(r.record_id, r));
   336→    return m;
   337→  }, [gewohnheitenVerwaltung]);
   338→
   339→  return { gewohnheitenVerwaltung, setGewohnheitenVerwaltung, taeglicherCheckIn, setTaeglicherCheckIn, taeglicheEintraege, setTaeglicheEintraege, loading, error, fetchAll, gewohnheitenVerwaltungMap };
   340→}
   341→```
