   359→import type { EnrichedTaeglicheEintraege, EnrichedTaeglicherCheckIn } from '@/types/enriched';
   360→import type { GewohnheitenVerwaltung, TaeglicheEintraege, TaeglicherCheckIn } from '@/types/app';
   361→import { extractRecordId } from '@/services/livingAppsService';
   362→
   363→// eslint-disable-next-line @typescript-eslint/no-explicit-any
   364→function resolveDisplay(url: string | undefined, map: Map<string, any>, ...fields: string[]): string {
   365→  if (!url) return '';
   366→  const id = extractRecordId(url);
   367→  if (!id) return '';
   368→  const r = map.get(id);
   369→  if (!r) return '';
   370→  return fields.map(f => String(r.fields[f] ?? '')).join(' ').trim();
   371→}
   372→
   373→interface TaeglicherCheckInMaps {
   374→  gewohnheitenVerwaltungMap: Map<string, GewohnheitenVerwaltung>;
   375→}
   376→
   377→export function enrichTaeglicherCheckIn(
   378→  taeglicherCheckIn: TaeglicherCheckIn[],
   379→  maps: TaeglicherCheckInMaps
   380→): EnrichedTaeglicherCheckIn[] {
   381→  return taeglicherCheckIn.map(r => ({
   382→    ...r,
   383→    gewohnheitenName: resolveDisplay(r.fields.gewohnheiten, maps.gewohnheitenVerwaltungMap, 'gewohnheit_name'),
   384→  }));
   385→}
   386→
   387→interface TaeglicheEintraegeMaps {
   388→  gewohnheitenVerwaltungMap: Map<string, GewohnheitenVerwaltung>;
   389→}
   390→
   391→export function enrichTaeglicheEintraege(
   392→  taeglicheEintraege: TaeglicheEintraege[],
   393→  maps: TaeglicheEintraegeMaps
   394→): EnrichedTaeglicheEintraege[] {
   395→  return taeglicheEintraege.map(r => ({
   396→    ...r,
   397→    gewohnheitName: resolveDisplay(r.fields.gewohnheit, maps.gewohnheitenVerwaltungMap, 'gewohnheit_name'),
   398→  }));
   399→}
