  // --- GEWOHNHEITEN_VERWALTUNG ---
  static async getGewohnheitenVerwaltung(): Promise<GewohnheitenVerwaltung[]> {
    const data = await callApi('GET', `/apps/${APP_IDS.GEWOHNHEITEN_VERWALTUNG}/records`);
